CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY,subject varchar(255) UNIQUE NOT NULL,email varchar(320),display_name varchar(160),avatar_url text,locale varchar(16) NOT NULL DEFAULT 'it-IT',timezone varchar(64) NOT NULL DEFAULT 'Europe/Rome',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS outbox_events(id uuid PRIMARY KEY,event_id uuid UNIQUE NOT NULL,event_type varchar(128) NOT NULL,schema_version integer NOT NULL,aggregate_id uuid NOT NULL,family_id uuid NULL,correlation_id uuid NOT NULL,causation_id uuid NULL,occurred_at timestamptz NOT NULL,payload jsonb NOT NULL,published_at timestamptz,attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_keys(key varchar(255) PRIMARY KEY,actor_user_id uuid NOT NULL,request_hash varchar(64) NOT NULL,status varchar(16) NOT NULL CHECK(status IN ('processing','completed','failed')),response_status integer,response_body jsonb,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
